(()=>{const controls=document.createElement('nav');controls.className='retro-preview-controls';controls.setAttribute('aria-label','Estilo do protótipo');const label=document.createElement('span');label.textContent='Protótipo de menu';controls.append(label);for(const [id,name]of [['gba','GBA clássico'],['gb','Game Boy']]){const b=document.createElement('button');b.textContent=name;b.setAttribute('aria-pressed',String(id==='gba'));b.onclick=()=>{document.body.classList.toggle('retro-monochrome',id==='gb');controls.querySelectorAll('button').forEach(button=>button.setAttribute('aria-pressed',String(button===b)))};controls.append(b)}document.body.append(controls)})();